class Solution:
    def minimumOperations(self, num: str) -> int:
        n = len(num)
        ans = n - 1 if '0' in num else n
        targets = {'00', '25', '50', '75'}
        for i in range(n):
            for j in range(i + 1, n):
                if num[i] + num[j] in targets:
                    ans = min(ans, n - 2 - i)
        return ans

