class Solution {
public:
    int minimumOperations(string num) {
        int n = num.size();
        int ans = num.find('0') != string::npos ? n - 1 : n;
        string targets[] = {"00", "25", "50", "75"};
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) {
                string p; p += num[i]; p += num[j];
                for (auto& t : targets)
                    if (p == t) ans = min(ans, n - 2 - i);
            }
        return ans;
    }
};

